 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the palette row repeated in three consecutive rows.
    palette = None
    for r in range(h - 2):
        if grid[r] == grid[r + 1] == grid[r + 2]:
            vals = [v for v in grid[r] if v]
            if len(vals) >= 2:
                palette = vals
                break
    if palette is None:
        raise ValueError("repeated palette row not found")

    # The main glyph is the largest 4-connected component of color 1.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append(comp)
    shape = max(comps, key=len)
    top = min(r for r, c in shape)
    left = min(c for r, c in shape)
    bottom = max(r for r, c in shape)
    right = max(c for r, c in shape)
    mask = {(r-top, c-left) for r, c in shape}
    sh = bottom - top + 1

    # Preserve the central color-1 copy and stack copies above/below it.
    one_idx = palette.index(1)
    start = top - one_idx * sh
    out = [row[:] for row in grid]
    for i, color in enumerate(palette):
        y0 = start + i * sh
        for dy, dx in mask:
            y, x = y0 + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out


